import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/redis/","title":"Redis","lang":"en-US","frontmatter":{},"git":{"updatedTime":1740223686000,"contributors":[{"name":"Noei","username":"Noei","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/Noei"},{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"160e4c7526d8c8ae36b6f71203e50947c1943ec9","time":1740223686000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add docker build content"},{"hash":"d88a3bd974577c93425b51025f7a6063aef8f041","time":1675526639000,"email":"logmanxsa@gmail.com","author":"Noei","message":"add redis content &#x26; other content"}]},"filePathRelative":"redis/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="redis" tabindex="-1"><a class="header-anchor" href="#redis"><span>Redis</span></a></h1><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">version:</span><span style="color:#9ECBFF;"> &#39;3.9&#39;</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">services:</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">  redis:</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    image:</span><span style="color:#9ECBFF;"> redis</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    container_name:</span><span style="color:#9ECBFF;"> redis</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">    ports:</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">      -</span><span style="color:#9ECBFF;"> 6379:6379</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="basic-command" tabindex="-1"><a class="header-anchor" href="#basic-command"><span>Basic command</span></a></h2><p>Set</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#79B8FF;">set</span><span style="color:#9ECBFF;"> foo</span><span style="color:#9ECBFF;"> butter</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Get</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">get</span><span style="color:#9ECBFF;"> foo</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Set and set expire</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#79B8FF;">set</span><span style="color:#9ECBFF;"> foo</span><span style="color:#9ECBFF;"> butter</span><span style="color:#9ECBFF;"> ex</span><span style="color:#F97583;"> &lt;</span><span style="color:#9ECBFF;">secon</span><span style="color:#E1E4E8;">d</span><span style="color:#F97583;">&gt;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Delete</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">del</span><span style="color:#9ECBFF;"> foo</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="config" tabindex="-1"><a class="header-anchor" href="#config"><span>Config</span></a></h2><ul><li>If your redis server down data in memory will removed all. You can config <a href="https://raw.githubusercontent.com/redis/redis/7.0/redis.conf" target="_blank" rel="noopener noreferrer">Default Config</a></li><li>If you use docker</li></ul><p>Check current dir in container</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">docker</span><span style="color:#9ECBFF;"> container</span><span style="color:#9ECBFF;"> exec</span><span style="color:#79B8FF;"> -it</span><span style="color:#9ECBFF;"> redis</span><span style="color:#9ECBFF;"> bash</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#79B8FF;">pwd</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Add in docker-compose</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">   volumes:</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">      -</span><span style="color:#9ECBFF;"> ./data/redis:/data</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">      -</span><span style="color:#9ECBFF;"> ./configs/redis.conf:/redis.conf</span></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">   command</span><span style="color:#9ECBFF;">:</span><span style="color:#9ECBFF;"> redis-server</span><span style="color:#9ECBFF;"> /redis.conf</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>Add <code>redis.conf</code> in <code>/configs</code> and copy <code>Default Config</code> to <code>redis.conf</code></li><li>Make dir <code>/data/redis</code></li></ul><p>If you use redis 6</p><ul><li>Find <code>bind</code> in <code>redis.conf</code> change value to <code>0.0.0.0</code></li></ul><p>If you use redis 7</p><ul><li>Find <code>bind</code> in <code>redis.conf</code> change value to <code>* -::*</code></li></ul><p>Note: Redis 7 has a number of security improvements and it&#39;s highly recommended to use them. One of them is to use redis auth, which you can configure by adding the following line to your redis.conf file:</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">requirepass</span><span style="color:#F97583;"> &lt;</span><span style="color:#9ECBFF;">passwor</span><span style="color:#E1E4E8;">d</span><span style="color:#F97583;">&gt;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>And then set the password from redis-cli with the command</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">127.0.0.1:6379</span><span style="color:#E1E4E8;">&gt; </span><span style="color:#9ECBFF;">auth</span><span style="color:#F97583;"> &lt;</span><span style="color:#9ECBFF;">passwor</span><span style="color:#E1E4E8;">d</span><span style="color:#F97583;">&gt;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>After you close redis server you will see <code>/data/reids/*.rdb</code></p><h2 id="snapshotting" tabindex="-1"><a class="header-anchor" href="#snapshotting"><span>Snapshotting</span></a></h2><p>Find <code>save &lt;seconds&gt; &lt;changes&gt; [&lt;seconds&gt; &lt;changes&gt; ...]</code> in <code>redis.conf</code><br> Unless specified otherwise, by default Redis will save the DB:</p><ul><li>After 3600 seconds (an hour) if at least 1 change was performed</li><li>After 300 seconds (5 minutes) if at least 100 changes were performed</li><li>After 60 seconds if at least 10000 changes were performed</li></ul><h3 id="redis-6" tabindex="-1"><a class="header-anchor" href="#redis-6"><span>Redis 6</span></a></h3><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>save 3600 1 </span></span></span>
<span class="line"><span class="line"><span>save 300 5 </span></span></span>
<span class="line"><span class="line"><span>save 60 10000</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="redis-7" tabindex="-1"><a class="header-anchor" href="#redis-7"><span>Redis 7</span></a></h3><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>save 3600 1 300 5 60 10000</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="disable-snap-short" tabindex="-1"><a class="header-anchor" href="#disable-snap-short"><span>Disable snap short</span></a></h3><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>save &quot;&quot;</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="append-only-mode" tabindex="-1"><a class="header-anchor" href="#append-only-mode"><span>APPEND ONLY MODE</span></a></h2><p>By default Redis asynchronously dumps the dataset on disk. This mode is good enough in many applications, but an issue with the Redis process or a power outage may result into a few minutes of writes lost (depending on the configured save points).</p><ul><li>Fix config</li></ul><div class="language-text line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span>save &quot;&quot;</span></span></span>
<span class="line"><span class="line"><span>...</span></span></span>
<span class="line"><span class="line"><span>appendonly no</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="monitoring" tabindex="-1"><a class="header-anchor" href="#monitoring"><span>Monitoring</span></a></h2><p>Learin in:</p><ul><li>influxdb</li><li>grafana</li></ul><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">docker</span><span style="color:#9ECBFF;"> compose</span><span style="color:#9ECBFF;"> up</span><span style="color:#9ECBFF;"> influxdb</span><span style="color:#9ECBFF;"> grafana</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><a href="https://redis.io/commands/" target="_blank" rel="noopener noreferrer">Learing Command</a></p>`,46)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};